    metrics = json.loads(Path("output/axp_metrics.json").read_text())
    chart_data = json.loads(Path("output/axp_chart_data.json").read_text())
    spec = json.loads(Path("benchmark/task_input.json").read_text())

    title = spec["brief"]["title"]

    period = metrics["period"]
    k = metrics["kpis"]
    extremes = metrics["extremes"]

    start = iso_date(period["start"])
    end = iso_date(period["end"])

    # KPI formatting
    cumulative_total_return = fmt_pct(float(k["cumulative_total_return"]), 1)
    cagr = fmt_pct(float(k["cagr"]), 2)
    max_drawdown = fmt_pct(float(k["max_drawdown"]), 1)
    ann_vol = fmt_pct(float(k["annualized_volatility"]), 1)
    total_div = fmt_num(float(k["total_dividends_per_share"]), 2)

    start_close = fmt_num(float(period["start_close"]), 3)
    end_close = fmt_num(float(period["end_close"]), 2)

    ath_close = fmt_num(float(extremes["all_time_high_close"]), 2)
    ath_date = iso_date(extremes["all_time_high_date"])
    atl_close = fmt_num(float(extremes["all_time_low_close"]), 3)
    atl_date = iso_date(extremes["all_time_low_date"])

    dd_peak_date = iso_date(k["max_drawdown_peak_date"])
    dd_trough_date = iso_date(k["max_drawdown_trough_date"])

    # Drawdown table
    worst_dd = metrics["worst_drawdowns"]

    dd_rows = []
    for row in worst_dd:
        dd_rows.append(
            {
                "mdd": float(row["max_drawdown"]),
                "peak_date": iso_date(row["peak_date"]),
                "trough_date": iso_date(row["trough_date"]),
                "recovery_date": iso_date(row["recovery_or_end_date"]),
                "peak_close": float(row["peak_close"]),
                "trough_close": float(row["trough_close"]),
                "duration_days": int(row["duration_days"]),
            }
        )

    decade_rows = metrics["decades"]

    # Dividend & split summaries
    div_meta = metrics["dividends"]
    split_meta = metrics["splits"]

    # Annual extremes
    annual_ext = metrics.get("annual_returns_extremes", {})

